import { useRef, useState } from "react";

export default function useSpeechRecognition({ onResult }) {
  const recognitionRef = useRef(null);
  const manualStopRef = useRef(false);
  const [isListening, setIsListening] = useState(false);
  const [transcript, setTranscript] = useState("");

  const start = () => {
    const SpeechRecognition =
      window.SpeechRecognition || window.webkitSpeechRecognition;

    if (!SpeechRecognition) {
      console.error("SpeechRecognition not supported in this browser.");
      return;
    }

    manualStopRef.current = false;

    const recognition = new SpeechRecognition();
    recognition.continuous = true;
    recognition.interimResults = true;
    recognition.lang = "en-US";

    let finalTranscript = "";

    recognition.onresult = (event) => {
      let interim = "";
      for (let i = event.resultIndex; i < event.results.length; i++) {
        const result = event.results[i];
        if (result.isFinal) {
          finalTranscript += result[0].transcript + " ";
        } else {
          interim += result[0].transcript;
        }
      }
      setTranscript((finalTranscript + interim).trim());
    };

    recognition.onerror = (e) => {
      console.error("SpeechRecognition error:", e.error);
    };

    recognition.onend = () => {
      // The browser can end recognition on its own after a stretch of
      // silence, even with continuous=true. If we didn't explicitly stop
      // it (via stop()), treat this as an interruption and restart —
      // don't wipe out what's already been said.
      if (!manualStopRef.current) {
        try {
          recognition.start();
          return; // stay "listening" — isListening/transcript untouched
        } catch (err) {
          console.error("Failed to auto-restart recognition:", err);
        }
      }
      setIsListening(false);
      const trimmed = finalTranscript.trim();
      if (trimmed) onResult(trimmed);
    };

    recognitionRef.current = recognition;
    recognition.start();
    setIsListening(true);
  };

  const stop = () => {
    manualStopRef.current = true;
    recognitionRef.current?.stop();
    setIsListening(false);
  };

  const reset = () => setTranscript("");

  return { start, stop, isListening, transcript, reset };
}
